// math_utils.h  (declaration)
int add(int a, int b);

// math_utils.c  (definition)
#include "math_utils.h"
int add(int a, int b) { return a + b; }

// main.c
#include <stdio.h>
#include "math_utils.h"     // declaration lets main.c reference add()

int main() {
    printf("%d\n", add(2, 3));
    return 0;
}

